
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_ft97_b_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_ft97_b", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.297860511783353e+00, -4.215447827073255e+00, -4.100133068407142e+00, -3.940750529243298e+00, -3.724337366837674e+00, -3.437923722310211e+00, -3.072625462098262e+00, -2.630998453252654e+00, -2.136910653467972e+00, -1.635643551078067e+00, -1.129545405492203e+00, -7.099316146776730e-01, -6.007112983125783e-01, -4.995505406395980e-01, -3.727158541955386e-01, -2.593339901794074e-01, -1.759885850302604e-01, -1.076585944121295e-01, -6.512013981810306e-02, -4.349157189365885e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


